/**
 * Phase K71 · Feb-2026 — Line-items editor with inline pencil edit,
 * bold Item + secondary muted long_description, and Service + Income
 * category dropdowns.
 *
 * Phase K80.a · Feb-2026 — Add + Delete line item affordances.
 *   • "+ Add line" button below the table (visible only when canEdit).
 *     Clicking appends an empty draft line and enters inline-edit mode
 *     on it immediately. Cancelling a NEW line discards it entirely.
 *   • Trash icon on each row (visible only when canEdit). Clicking hides
 *     the row locally and surfaces an in-component Undo toast for 5s.
 *     If not undone, onLinesUpdated fires with the deleted row removed.
 *   • Only one pending delete at a time. While a delete is pending the
 *     Add-line and other trash buttons are disabled to keep state simple.
 *   • Category-required validation is unchanged: an added line still has
 *     to pass the same Service + Income picker rule as any legacy row
 *     switching into edit mode. Rows added and then Cancelled/Undone
 *     never round-trip to the server.
 *
 * Contract:
 *   - Renders the line-items table for /quotes/:id and /invoices/:id.
 *   - Column header renamed from "Description" → "Item" (spec K71).
 *   - Pencil icon appears on each row when ``canEdit`` is true (draft
 *     doc AND admin/super role). Clicking swaps the row into an inline
 *     form with fields: Item (description), Qty, Unit price, Description
 *     (multi-line, 500-char cap), Service Category, Income Category.
 *   - Save = onLinesUpdated(fullMutatedArray) — parent PUTs the whole
 *     array to /api/quotes/:id (server recomputes totals). Cancel reverts.
 *     Enter = Save, Esc = Cancel.
 *   - Legacy line items (neither service_category_id nor
 *     income_category_id present) show a subtle "Uncategorized" badge.
 *   - PDF/portal never render this component (staff-only surface).
 */
import React, { useEffect, useMemo, useRef, useState } from "react";
import { Pencil, X, Check, Plus, Trash2, Undo2, AlertCircle, Search } from "lucide-react";
import { colors, money } from "@/theme";
import CategoryPicker, {
  loadCategories as _loadCatsByKind,
} from "@/components/income/CategoryPicker";
// Task G · Feb-2026 — Pricebook-driven line-item picker.
// Replaces the P16.1 ``MasterServiceCombobox`` (which read from the
// ``/master-services`` shadow catalog) with a debounced live search
// against the CRM's primary Pricebook catalog (``GET /api/items``,
// tenant-scoped after P59 HIGH #1 fix). Picking a row auto-fills
// title / description / unit_price / service_category_id, plus
// income_category_id iff the item's item_type !== "service" (per
// backend rule: services cannot carry income_category / supplier
// pricing — see routers/items.py :183-202).
import { api } from "@/api";
const MAX_LONG_DESC = 500;
// Pricebook picker debounce — 250 ms after last keystroke, then
// fire the search. Empty string → NO request, dropdown closed.
const PICKER_DEBOUNCE_MS = 250;
const PICKER_MAX_RESULTS = 50;
const UNDO_WINDOW_MS = 5000;

// Feb-2026 · Stable-id keys + duplicate-row guard.
//
// Line items acquire their canonical id (``li.id``) from the server on
// first PUT.  Locally-drafted lines (fresh Add-line click, pre-save)
// have no id yet, so we mint a client-only ``_uid`` when the row
// enters state and reuse it across renders — never per-render, never
// falling back to the array index (React key anti-pattern).
//
// ``_normalize(list)`` runs at every state-boundary and:
//   1. Attaches a ``_uid`` to any incoming line that still has no
//      stable key.
//   2. Filters out any subsequent occurrence of the same stable key,
//      guaranteeing the render pipeline never emits two rows with
//      matching ``key=`` — even during an optimistic add/delete/undo
//      cycle where the reducer/effect could momentarily hold both an
//      optimistic and a server-confirmed copy.
function _lineKey(li) {
  return li?.id ?? li?._id ?? li?._uid ?? li?.uid ?? null;
}

function _mintUid() {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }
  return `_uid-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

function _ensureUid(li) {
  if (_lineKey(li)) return li;
  return { ...li, _uid: _mintUid() };
}

function _normalize(list) {
  const seen = new Set();
  const out = [];
  for (const raw of list || []) {
    if (!raw) continue;
    const li = _ensureUid(raw);
    const k = _lineKey(li);
    // Dedup by stable id. Rows without any id are extremely rare (a
    // hypothetical caller could bypass ``_ensureUid``), but we keep
    // them to avoid silently swallowing user data — they simply
    // aren't dedup-comparable.
    if (k != null) {
      if (seen.has(k)) continue;
      seen.add(k);
    }
    out.push(li);
  }
  return out;
}

function LegacyBadge({ testid = "k71-uncategorized-badge" }) {
  return (
    <span
      className="px-1.5 py-0.5 rounded-md text-[10px] font-bold uppercase tracking-wide"
      style={{ backgroundColor: "#FEF3C7", color: "#92400E" }}
      data-testid={testid}
    >
      Uncategorized
    </span>
  );
}

function isLegacyLine(li) {
  // Phase K71 · Feb-2026 — K71-touched iff either category field is
  // a string (matches backend routers/income_categories.py rule).
  const hasSvc = typeof li.service_category_id === "string";
  const hasInc = typeof li.income_category_id === "string";
  return !hasSvc && !hasInc;
}

// ────────────────────────────────────────────────────────────────
// Task G · Feb-2026 — Pricebook picker (K71-only).
//
// Debounced (250 ms) live search against ``GET /api/items``. The
// endpoint is tenant-scoped and soft-delete-excluding after the
// P59 HIGH #1 fix, and accepts ``search`` / ``active`` / ``limit``
// query params (see routers/items.py :93-170).
//
// Stale-response discipline: a monotonic ``_reqSeq`` counter is
// bumped on every keystroke and captured before the ``api.get``
// call. When the response resolves, we discard it if a newer
// keystroke has since bumped the counter. Simpler than an
// AbortController plumbing since ``api.get`` doesn't expose an
// ``AbortSignal`` hook.
//
// Contract:
//   • ``value`` (string) — the current NAME / description string.
//     Free-typing bubbles ``onTextChange(name)`` on every keystroke.
//     No overwrite of parent price / category state on free-type.
//   • ``onPick(item)`` fires ONCE when the user clicks a dropdown
//     row. Full item doc is passed through — caller decides what
//     to auto-fill.
//   • Enter key is NOT hijacked — bubbles up to the surrounding
//     EditableRow ``handleKey`` (Enter → Save). Escape closes the
//     dropdown without preventing default (Escape → row Cancel).
//   • Empty query → no request fired, no dropdown open.
//
// Testids:
//   • Wrapper div: ``k71-input-item-{index}`` (LEGACY preserved).
//   • Input:       ``k71-input-item-{index}-input`` (LEGACY preserved
//                   — see /app/frontend/src/test/k71-line-items-
//                   editor.test.jsx :232 which queries it directly).
//   • New picker sub-elements carry the fresh ``k71-pricebook-
//     search-*`` namespace. Only one EditableRow renders at a time
//     (single ``editIndex`` in K71 state), so no per-index suffix
//     is needed on the picker-specific testids.
// ────────────────────────────────────────────────────────────────
function K71PricebookPicker({ index, value, onTextChange, onPick, placeholder }) {
  const [open, setOpen] = useState(false);
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const wrapRef = useRef(null);
  // Monotonic request id — every keystroke bumps this. Response
  // handlers compare against the LATEST value and discard stale
  // ones. Same pattern React Router / TanStack Query use for
  // request-cancellation-lite when native AbortSignal isn't wired.
  const reqSeqRef = useRef(0);

  // Outside-click closes the dropdown.
  useEffect(() => {
    if (!open) return undefined;
    const onDocClick = (e) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target)) {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [open]);

  // Debounced search. Cleared / empty ``value`` short-circuits — no
  // request fired, results wiped, dropdown left in its current
  // open/closed state (usually closed since focus-empty won't fire).
  useEffect(() => {
    const trimmed = (value || "").trim();
    if (!trimmed) {
      setResults([]);
      setLoading(false);
      return undefined;
    }
    setLoading(true);
    const mySeq = ++reqSeqRef.current;
    const t = setTimeout(async () => {
      try {
        const params = new URLSearchParams({
          search: trimmed,
          active: "true",
          limit: String(PICKER_MAX_RESULTS),
        }).toString();
        const rows = await api.get(`/items?${params}`);
        // Stale response — a newer keystroke bumped the counter
        // after we captured ``mySeq``. Drop this batch.
        if (mySeq !== reqSeqRef.current) return;
        setResults(Array.isArray(rows) ? rows : []);
      } catch {
        if (mySeq !== reqSeqRef.current) return;
        setResults([]);
      } finally {
        if (mySeq === reqSeqRef.current) setLoading(false);
      }
    }, PICKER_DEBOUNCE_MS);
    return () => clearTimeout(t);
  }, [value]);

  const handleTextChange = (next) => {
    onTextChange(next);
    // Open the dropdown on any keystroke so the user sees the
    // search state (loading indicator or results). ``useEffect``
    // above handles the empty-value short-circuit for the
    // NO-request contract.
    if ((next || "").trim()) setOpen(true);
  };

  const handlePick = (row) => {
    onPick(row);
    setOpen(false);
  };

  const trimmed = (value || "").trim();
  // Dropdown visibility: open AND user has typed something. The
  // empty-value branch short-circuits above so open==true with no
  // ``trimmed`` never fires a request; we ALSO keep the dropdown
  // panel out of the DOM in that state so tests can assert
  // "no dropdown before keystrokes".
  const showDropdown = open && trimmed.length > 0;

  return (
    <div
      ref={wrapRef}
      className="relative"
      data-testid={`k71-input-item-${index}`}
    >
      <div className="relative">
        <Search
          size={14}
          className="absolute left-2.5 top-1/2 -translate-y-1/2 pointer-events-none"
          style={{ color: colors.searchIcon || colors.muted }}
        />
        <input
          type="text"
          value={value || ""}
          onChange={(e) => handleTextChange(e.target.value)}
          onFocus={() => { if (trimmed) setOpen(true); }}
          onClick={() => { if (trimmed) setOpen(true); }}
          placeholder={placeholder}
          className="w-full text-sm rounded-lg py-2 pl-8 pr-3"
          style={{
            background: colors.surface,
            border: `1px solid ${colors.border}`,
            color: colors.onSurface,
          }}
          data-testid={`k71-input-item-${index}-input`}
          autoComplete="off"
        />
      </div>

      {showDropdown ? (
        <div
          className="absolute z-[60] left-0 right-0 mt-1 rounded-lg overflow-hidden shadow-lg"
          style={{
            background: colors.surface,
            border: `1px solid ${colors.border}`,
            maxHeight: 300,
            overflowY: "auto",
          }}
          data-testid="k71-pricebook-search-dropdown"
        >
          {loading ? (
            <div
              className="px-3 py-2 text-xs"
              style={{ color: colors.muted }}
              data-testid="k71-pricebook-search-loading"
            >
              Searching pricebook…
            </div>
          ) : null}
          {!loading && results.length === 0 ? (
            <div
              className="px-3 py-2 text-xs"
              style={{ color: colors.muted }}
              data-testid="k71-pricebook-search-empty"
            >
              No pricebook items match &ldquo;{trimmed}&rdquo;.
              You can type a one-off name — it&rsquo;ll save on this line only.
            </div>
          ) : null}
          {!loading && results.map((row, i) => {
            const svcName = row.service_category_name || "";
            const incName = row.income_category_name || "";
            const legacyCat = row.category || "";
            return (
              <button
                key={row.id ?? i}
                type="button"
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => handlePick(row)}
                className="w-full text-left px-3 py-2 text-sm flex flex-col gap-1 hover:bg-slate-50"
                style={{
                  color: colors.onSurface,
                  borderBottom: `1px solid ${colors.border}`,
                }}
                data-testid={`k71-pricebook-search-item-${i}`}
              >
                <div className="flex items-baseline justify-between gap-3">
                  <span className="font-semibold truncate">{row.name}</span>
                  <span
                    className="text-xs tabular-nums shrink-0"
                    style={{ color: colors.muted }}
                  >
                    {money(Number(row.unit_price || 0))}
                  </span>
                </div>
                {row.description ? (
                  <div
                    className="text-xs truncate"
                    style={{ color: colors.muted }}
                    title={row.description}
                  >
                    {row.description}
                  </div>
                ) : null}
                {(svcName || incName || legacyCat) ? (
                  <div className="flex items-center flex-wrap gap-1 mt-0.5">
                    {svcName ? (
                      <span
                        className="px-1.5 py-0.5 rounded text-[10px] font-semibold uppercase tracking-wide"
                        style={{
                          background: "#DCFCE7",
                          color: "#166534",
                        }}
                      >
                        {svcName}
                      </span>
                    ) : null}
                    {incName ? (
                      <span
                        className="px-1.5 py-0.5 rounded text-[10px] font-semibold uppercase tracking-wide"
                        style={{
                          background: "#DBEAFE",
                          color: "#1E40AF",
                        }}
                      >
                        {incName}
                      </span>
                    ) : null}
                    {(!svcName && !incName && legacyCat) ? (
                      <span
                        className="px-1.5 py-0.5 rounded text-[10px] font-semibold uppercase tracking-wide"
                        style={{
                          background: "#F1F5F9",
                          color: "#475569",
                        }}
                      >
                        {legacyCat}
                      </span>
                    ) : null}
                  </div>
                ) : null}
              </button>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}

function EditableRow({ line, index, onSave, onCancel }) {
  const [description, setDescription] = useState(line.description || "");
  const [longDesc, setLongDesc] = useState(line.long_description || "");
  const [quantity, setQuantity] = useState(String(line.quantity ?? 1));
  const [unitPrice, setUnitPrice] = useState(String(line.unit_price ?? 0));
  const [serviceCategoryId, setServiceCategoryId] = useState(
    line.service_category_id || ""
  );
  const [incomeCategoryId, setIncomeCategoryId] = useState(
    line.income_category_id || ""
  );
  // Feb-2026 · Pricebook × Profit-Reporting Phase 2 — per-line
  // admin overrides. Empty string in state = "no override, use
  // the snapshot at read". Serialised as null on save.
  const [wholesaleOverride, setWholesaleOverride] = useState(
    line.wholesale_cost_override == null ? "" : String(line.wholesale_cost_override)
  );
  const [laborOverride, setLaborOverride] = useState(
    line.labor_cost_override == null ? "" : String(line.labor_cost_override)
  );
  const [serviceCategoryOverride, setServiceCategoryOverride] = useState(
    line.service_category_id_override || ""
  );
  const [incomeCategoryOverride, setIncomeCategoryOverride] = useState(
    line.income_category_id_override || ""
  );
  const [attempted, setAttempted] = useState(false);
  // Task G · Feb-2026 — the auto-focus ``nameRef`` that used
  // to target the raw <input> is dropped: ``K71PricebookPicker``
  // renders its own internal input and manages focus + dropdown-
  // open state on user click / keystroke.

  // Feb-2026 · Phase 2 — Live margin display. Uses OVERRIDE-first
  // resolution to match backend ``effective_*`` semantics so admins
  // see the margin they'll actually book at the reporting layer.
  const wholesaleSnap = Number(line.wholesale_price_snapshot ?? 0);
  const laborSnap = Number(line.labor_cost_snapshot ?? 0);
  const effWholesale = wholesaleOverride === "" ? wholesaleSnap : Number(wholesaleOverride) || 0;
  const effLabor = laborOverride === "" ? laborSnap : Number(laborOverride) || 0;
  const retailPerUnit = Number(unitPrice) || 0;
  const qtyN = Number(quantity) || 0;
  const lineRevenue = retailPerUnit * qtyN;
  const lineCost = (effWholesale + effLabor) * qtyN;
  const marginDollar = lineRevenue - lineCost;
  const marginPct = lineRevenue > 0 ? (marginDollar / lineRevenue) * 100 : 0;

  const commit = () => {
    setAttempted(true);
    if (!description.trim()) return;
    if (!serviceCategoryId || !incomeCategoryId) return;
    if ((longDesc || "").length > MAX_LONG_DESC) return;
    // Validate override numeric fields are non-negative when set.
    if (wholesaleOverride !== "" && (Number.isNaN(Number(wholesaleOverride)) || Number(wholesaleOverride) < 0)) return;
    if (laborOverride !== "" && (Number.isNaN(Number(laborOverride)) || Number(laborOverride) < 0)) return;
    onSave({
      ...line,
      description: description.trim(),
      long_description: longDesc || null,
      quantity: Number(quantity) || 0,
      unit_price: Number(unitPrice) || 0,
      service_category_id: serviceCategoryId,
      income_category_id: incomeCategoryId,
      // Feb-2026 · Phase 2 — carry override fields through the save.
      // Empty-string in state maps to explicit null so the backend
      // treats it as "no override" (revert to snapshot).
      wholesale_cost_override: wholesaleOverride === "" ? null : Number(wholesaleOverride),
      labor_cost_override: laborOverride === "" ? null : Number(laborOverride),
      service_category_id_override: serviceCategoryOverride || null,
      income_category_id_override: incomeCategoryOverride || null,
    });
  };

  const handleKey = (e) => {
    if (e.key === "Escape") { e.preventDefault(); onCancel(); }
    if (e.key === "Enter" && !e.shiftKey && e.target.tagName !== "TEXTAREA") {
      e.preventDefault();
      commit();
    }
  };

  return (
    <tr
      style={{ borderBottom: `1px solid ${colors.divider}`,
                background: colors.surfaceSecondary }}
      data-testid={`k71-row-edit-${index}`}
      onKeyDown={handleKey}
    >
      <td colSpan={5} className="px-2 py-3">
        <div className="grid grid-cols-12 gap-2">
          <div className="col-span-12 sm:col-span-5">
            <label className="text-[10px] uppercase font-bold block mb-1"
                    style={{ color: colors.muted }}>Item</label>
            {/* Task G · Feb-2026 — Pricebook picker in place of the
                 legacy MasterServiceCombobox. Debounced 250ms search
                 against ``GET /api/items?search=…&active=true&limit=50``
                 (tenant-scoped after P59 HIGH #1). Picking a row
                 auto-fills:
                   • description  ← item.name
                   • long_desc    ← item.description (only if present;
                                     preserves any user-typed override)
                   • unit_price   ← item.unit_price
                   • service_cat  ← item.service_category_id (direct
                                     id assignment; no name→id lookup
                                     since the endpoint already
                                     returns the tenant's real ids)
                   • income_cat   ← item.income_category_id, ONLY IF
                                     item.item_type !== "service"
                                     (backend rule at items.py :183-
                                     202 — services can't own an
                                     income_category or supplier
                                     pricing). Service items leave
                                     the income cell untouched so
                                     the operator picks manually via
                                     the CategoryPicker below.
                 Free-typing (no pick) still saves the raw string on
                 commit — backwards-compatible with legacy line items
                 that never lived in the pricebook. */}
            <K71PricebookPicker
              index={index}
              value={description}
              onTextChange={(next) => setDescription(next)}
              onPick={(item) => {
                setDescription(item.name || "");
                // Only overwrite description when the item has one —
                // preserves a user-typed note if they picked a row
