export default function K71LineItemsEditor({
  doc, canEdit, onLinesUpdated, onError,
}) {
  const [localItems, setLocalItems] = useState(() =>
    _normalize(doc.line_items || []),
  );
  const [editIndex, setEditIndex] = useState(null);
  // Track the index of a locally-added-but-not-yet-saved line so
  // Cancel discards it entirely (vs reverting an existing row).
  const [newLineIndex, setNewLineIndex] = useState(null);
  // Single-slot pending delete with 5s undo window.
  //   { line, originalIndex, timeoutId }
  const [pendingDelete, setPendingDelete] = useState(null);

  // Phase P40 · Feb-2026 — active-category id sets for stale-
  // reference detection on prefilled rows. Fail-open policy: if
  // either taxonomy resolves to an EMPTY list (genuinely empty
  // OR the underlying fetch failed — ``loadCategories`` swallows
  // errors into ``[]``), the guard stays disabled and the backend
  // validator remains the durable safety net. In practice each
  // tenant boot-seeds default categories, so a truly-empty list
  // means the fetch failed.
  const [activeIds, setActiveIds] = useState({
    income: null, service: null,  // null = still loading; Set = ready
  });

  useEffect(() => {
    let cancelled = false;
    Promise.all([
      _loadCatsByKind("income"),
      _loadCatsByKind("service"),
    ]).then(([inc, svc]) => {
      if (cancelled) return;
      setActiveIds({
        income: new Set(
          (inc || [])
            .filter((c) => !c.is_archived)
            .map((c) => c.id),
        ),
        service: new Set(
          (svc || [])
            .filter((c) => !c.is_archived)
            .map((c) => c.id),
        ),
      });
    });
    return () => { cancelled = true; };
  }, []);

  // Ref so the delayed onLinesUpdated call captures the LATEST
  // localItems (in case the user adds another line during the window).
  const localItemsRef = useRef(localItems);
  useEffect(() => { localItemsRef.current = localItems; }, [localItems]);

  // Sync when parent doc changes (after a save or full reload).
  // Only re-sync when nothing is in flight locally — otherwise we'd
  // wipe an unsaved add or an active undo window. Every set-state
  // boundary funnels through ``_normalize`` so client-generated
  // ``_uid`` values are attached (for new lines) and any duplicate
  // stable-id rows the server briefly returns are collapsed.
  useEffect(() => {
    if (editIndex === null && pendingDelete === null && newLineIndex === null) {
      setLocalItems(_normalize(doc.line_items || []));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [doc.line_items]);

  // Clear any lingering timeout on unmount so we don't fire a save
  // against a stale parent after the page navigates away.
  useEffect(() => {
    return () => {
      if (pendingDelete?.timeoutId) {
        clearTimeout(pendingDelete.timeoutId);
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const items = localItems;
  const canAdd = canEdit && editIndex === null && pendingDelete === null;

  const saveLine = async (idx, updatedLine) => {
    // Preserve the row's existing stable id (``id`` or ``_uid``) on
    // the mutated copy — the edit form spreads ``...line`` inside
    // ``EditableRow.commit`` so this is already true in the common
    // path, but we defensively re-normalize here so a caller that
    // reshapes the object never breaks the dedup invariant.
    const next = _normalize(items.map((li, i) => (i === idx ? updatedLine : li)));
    try {
      // Optimistic: reflect in local state immediately so the
      // "Cancel" of a subsequent add doesn't wipe the fresh save.
      setLocalItems(next);
      const res = await onLinesUpdated(next);
      if (res !== false) {
        setEditIndex(null);
        // Clear new-line marker — the row is now persisted.
        if (newLineIndex === idx) setNewLineIndex(null);
      } else {
        // Save rejected — leave the row in edit mode so the user
        // can fix the error and retry.
      }
    } catch (e) {
      onError?.(e?.data?.detail || e?.message || "Save failed");
    }
  };

  const cancelLine = (idx) => {
    if (newLineIndex === idx) {
      // Discard the never-saved draft entirely.
      setLocalItems((prev) => _normalize(prev.filter((_, i) => i !== idx)));
      setNewLineIndex(null);
    }
    setEditIndex(null);
  };

  const handleAddLine = () => {
    if (!canAdd) return;
    // Mint the client-only ``_uid`` at insertion time so React's
    // ``key=`` prop stays STABLE across every subsequent render of
    // this row, including the pending-save round-trip.
    const empty = {
      description: "",
      quantity: 1,
      unit_price: 0,
      service_category_id: "",
      income_category_id: "",
      long_description: "",
      _uid: _mintUid(),
    };
    setLocalItems((prev) => {
      const next = _normalize([...prev, empty]);
      const newIdx = next.length - 1;
      setNewLineIndex(newIdx);
      setEditIndex(newIdx);
      return next;
    });
  };

  const handleDelete = (idx) => {
    if (!canEdit || pendingDelete !== null) return;
    const line = items[idx];
    const nextLocal = _normalize(items.filter((_, i) => i !== idx));
    setLocalItems(nextLocal);
    const timeoutId = setTimeout(async () => {
      setPendingDelete(null);
      try {
        // Use the ref so any add/edit that happened during the
        // window is included.
        await onLinesUpdated(localItemsRef.current);
      } catch (e) {
        onError?.(e?.data?.detail || e?.message || "Delete failed");
      }
    }, UNDO_WINDOW_MS);
    setPendingDelete({ line, originalIndex: idx, timeoutId });
  };

  const handleUndo = () => {
    if (!pendingDelete) return;
    clearTimeout(pendingDelete.timeoutId);
    setLocalItems((prev) => {
      const restored = prev.slice();
      const at = Math.min(pendingDelete.originalIndex, restored.length);
      restored.splice(at, 0, pendingDelete.line);
      // ``_normalize`` also filters — if the parent has already
      // reloaded and the server row snuck back in during the undo
      // window, we won't emit two rows with the same key.
      return _normalize(restored);
    });
    setPendingDelete(null);
  };

  // K71 gap detection for the banner + inline row highlighting.
  // Uses the same string-type rule as the backend so a legacy line
  // returned as ``service_category_id: null`` doesn't spuriously
  // enter the banner count.
  const gaps = items
    .map((li, i) => {
      const hasSvc = typeof li.service_category_id === "string";
      const hasInc = typeof li.income_category_id === "string";
      if (!hasSvc && !hasInc) return null;
      const svcVal = hasSvc ? li.service_category_id.trim() : "";
      const incVal = hasInc ? li.income_category_id.trim() : "";
      return (!svcVal || !incVal) ? i : null;
    })
    .filter((v) => v !== null);

  // Phase P40 · Feb-2026 — upstream cure for "UUIDs in Income by
  // Category". A K71 line whose service_category_id or
  // income_category_id no longer maps to an ACTIVE tenant category
  // (archived, deleted, stale from a legacy write) is flagged the
  // same way as the empty-string gap: red border on the read row,
  // aria-invalid, inline error, and a form-level banner.
  //
  // Guard: only trust activeIds when BOTH sets have loaded AND
  // BOTH are non-empty. An empty list (real or fetch-failure via
  // ``loadCategories`` swallow-catch) means we can't tell active
  // from stale — fail-open, backend validator handles it on save.
  const activeIdsReady = activeIds.income instanceof Set
    && activeIds.service instanceof Set
    && activeIds.income.size > 0
    && activeIds.service.size > 0;
  const staleIndices = useMemo(() => {
    if (!activeIdsReady) return new Set();
    const out = new Set();
    items.forEach((li, i) => {
      const svcVal = typeof li.service_category_id === "string"
        ? li.service_category_id.trim() : "";
      const incVal = typeof li.income_category_id === "string"
        ? li.income_category_id.trim() : "";
      // Skip legacy grandfathered rows (neither field present).
      if (!svcVal && !incVal) return;
      // Skip rows already caught by the empty-string gap detector —
      // they render the same banner slot.
      if (!svcVal || !incVal) return;
      if (!activeIds.service.has(svcVal)) { out.add(i); return; }
      if (!activeIds.income.has(incVal)) { out.add(i); return; }
    });
    return out;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items, activeIdsReady, activeIds.income, activeIds.service]);

  const invalidCount = gaps.length + staleIndices.size;
  const hasInvalidRows = invalidCount > 0;

  return (
    <div>
      {gaps.length && canEdit ? (
        <div
          className="rounded-xl p-3 mb-3 text-sm flex items-start gap-2"
          style={{ background: "#FEE2E2", color: "#7F1D1D",
                    border: "1px solid #FCA5A5" }}
          data-testid="k71-gap-banner"
        >
          <span className="font-semibold">Missing categories:</span>
          <span>
            {gaps.length === 1
              ? "1 line item is missing a Service or Income category."
              : `${gaps.length} line items are missing a Service or Income category.`}{" "}
            You must set them before sending, approving or converting.
          </span>
        </div>
      ) : null}
      {staleIndices.size > 0 && canEdit ? (
        <div
          className="rounded-xl p-3 mb-3 text-sm flex items-start gap-2"
          style={{ background: "#FEE2E2", color: "#7F1D1D",
                    border: "1px solid #FCA5A5" }}
          data-testid="k71-stale-category-banner"
        >
          <AlertCircle size={14} className="mt-0.5 shrink-0" />
          <div>
            <span className="font-semibold">Inactive categories:</span>{" "}
            {staleIndices.size === 1
              ? "1 line item references a category that is no longer active."
              : `${staleIndices.size} line items reference categories that are no longer active.`}{" "}
            Pick a valid category from the list on each highlighted row.
          </div>
        </div>
      ) : null}
      <table
        className={`w-full text-sm ${
          editIndex === null ? "hidden sm:table" : ""
        }`}
        data-testid="k71-line-items-table"
      >
        <thead>
          <tr style={{ borderBottom: `1px solid ${colors.divider}` }}>
            <th className="text-left px-2 py-2 font-semibold"
                style={{ color: colors.onSurfaceSecondary }}
                data-testid="k71-th-item">Item</th>
            <th className="text-right px-2 py-2 font-semibold"
                style={{ color: colors.onSurfaceSecondary }}>Qty</th>
            <th className="text-right px-2 py-2 font-semibold"
                style={{ color: colors.onSurfaceSecondary }}>Unit</th>
            <th className="text-right px-2 py-2 font-semibold"
                style={{ color: colors.onSurfaceSecondary }}>Total</th>
            <th className="px-2 py-2 w-20"></th>
          </tr>
        </thead>
        <tbody>
          {items.map((li, i) => (
            editIndex === i ? (
              <EditableRow
                key={_lineKey(li)}
                line={li}
                index={i}
                onSave={(updated) => saveLine(i, updated)}
                onCancel={() => cancelLine(i)}
              />
            ) : (
              <ReadRow
                key={_lineKey(li)}
                line={li}
                index={i}
                canEdit={canEdit && editIndex === null}
                deleteDisabled={pendingDelete !== null}
                stale={staleIndices.has(i)}
                onEdit={setEditIndex}
                onDelete={handleDelete}
              />
            )
          ))}
        </tbody>
      </table>

      {/* Feb-2026 · Responsive Quote/Estimate follow-up — mobile
          stacked-card fallback for < sm. Kept out of the DOM
          entirely while any row is in edit mode (``editIndex !==
          null``) so the ``<tr>``-based ``EditableRow`` becomes
          the sole visible surface + owns focus. Distinct
          ``-mobile`` testids preserve every existing table-based
          test assertion. */}
      {editIndex === null ? (
        <ul
          className="sm:hidden mt-2 flex flex-col gap-2 list-none p-0"
          data-testid="k71-line-items-cards"
        >
          {items.map((li, i) => (
            <MobileCard
              key={_lineKey(li)}
              line={li}
              index={i}
              canEdit={canEdit}
              deleteDisabled={pendingDelete !== null}
              stale={staleIndices.has(i)}
              onEdit={setEditIndex}
              onDelete={handleDelete}
            />
          ))}
        </ul>
      ) : null}

      {canEdit ? (
        <div className="mt-3 flex justify-start">
          <button
            type="button"
            onClick={handleAddLine}
            disabled={!canAdd}
            className="text-xs font-semibold flex items-center gap-1 px-2 py-1 rounded disabled:opacity-40 disabled:cursor-not-allowed"
            style={{ color: colors.brand,
                      border: `1px dashed ${colors.brand}` }}
            data-testid="k71-add-line-btn"
            title={pendingDelete !== null
              ? "Finish the pending delete first"
              : editIndex !== null
                ? "Save or cancel the current row first"
                : "Add a new line item"}
          >
            <Plus size={12} /> Add line
          </button>
        </div>
      ) : null}

      {pendingDelete ? (
        <UndoToast onUndo={handleUndo} testid="k71-undo-toast" />
      ) : null}

      {/* Phase P40 · Feb-2026 — form-level guard message. Rendered
          whenever ANY row is flagged (missing OR stale category).
          This is the "one or more line items has an inactive
          category — fix highlighted rows to save" copy the caller
          spec asks for. Doc-level Save buttons (send/approve/
          convert) already gate on ``check_line_items_k71_gaps``
          server-side; this banner exists so the operator sees the
          problem BEFORE clicking Send / Approve. */}
      {hasInvalidRows && canEdit ? (
        <div
          className="rounded-xl p-3 mt-3 text-sm flex items-start gap-2"
          role="alert"
          style={{ background: "#FEE2E2", color: "#7F1D1D",
                    border: "1px solid #FCA5A5" }}
          data-testid="k71-form-invalid-message"
        >
          <AlertCircle size={14} className="mt-0.5 shrink-0" />
          <span>
            One or more line items has an inactive or missing category.
            Fix highlighted rows to save.
          </span>
        </div>
      ) : null}
    </div>
  );
}
